"""Merge the reviewed Odia year-list snapshot into the catalog without deleting existing records."""
import hashlib,json,re,pathlib
root=pathlib.Path(__file__).resolve().parents[1]
refs=json.loads((root/'scripts/odia-references.json').read_text());curated=json.loads((root/'dist/movies.json').read_text());archive=json.loads((root/'dist/archive.json').read_text())
for row in refs:
 if len(row['title'])<3 or row['title'].isdigit() or row['director'].isdigit():continue
 title=row['title'].strip();year=int(row['year']);key=(title.casefold(),year)
 if any((m['title'].casefold(),m['year'])==key for m in curated+archive):continue
 raw='odia|'+str(year)+'|'+title.casefold();id=400000000000000+int(hashlib.sha256(raw.encode()).hexdigest()[:12],16)
 cast=[p.strip() for p in re.split(r',|;| and ',row['cast']) if p.strip() and len(p.strip())<100]
 archive.append(dict(id=id,title=title,year=year,genres=['Uncategorized'],cast=cast or ['Not indexed'],director=row['director'].strip(),runtime=None,poster='',summary='Synopsis has not yet been added to this catalog entry.',trailer='',score=None,providers=[],source='Wikipedia',sourceUrl=row['sourceUrl'],mediaType='movie',releaseDate=None,updatedAt='2026-10-27',featured=False,metadataStatus='index-only',regionOfOrigin='Odia',industry='Ollywood',languages=['Odia'],languageSource='Wikipedia Odia release list'))

def add(movie):
 global archive,curated
 key=(movie['title'].casefold(),movie['year']);old=next((m for m in curated+archive if (m['title'].casefold(),m['year'])==key),None)
 if old:movie['id']=old['id'];curated=[m for m in curated if m['id']!=old['id']];archive=[m for m in archive if m['id']!=old['id']]
 curated.append(movie)
base=dict(mediaType='movie',source='Wikipedia',runtime=None,score=None,providers=[],releaseDate=None,updatedAt='2026-10-27',featured=True,metadataStatus='enriched',languageSource='Original-language credit')
add(dict(base,id=610000000001,title='DAMaN',year=2022,genres=['Drama','Adventure'],cast=['Babushaan Mohanty','Dipanwit Dashmohapatra'],director='Vishal Mourya and Debi Prasad Lenka',runtime=121,summary='A young doctor posted to a remote region of Odisha works with local communities to fight malaria and overcome barriers to treatment.',poster='https://images.justwatch.com/poster/297596886/s718/daman.jpg',trailer='MOckS35r8yE',sourceUrl='https://en.wikipedia.org/wiki/Daman_(2022_film)',languages=['Odia'],industry='Ollywood',regionOfOrigin='Odia'))
add(dict(base,id=610000000002,title='Pratikshya',year=2022,genres=['Drama','Family'],cast=['Dipanwit Dashmohapatra','Choudhury Jayaprakash Das','Barsha Patnaik','Sreela Tripathy','Siddhanta Mahapatra'],director='Anupam Patnaik',summary='A young job seeker confronts family expectations and a medical crisis as he pursues a government position.',poster='https://m.media-amazon.com/images/M/MV5BN2U0ZjJiNWUtM2M5Ni00ZDEzLWFlMTAtZWU2ZWQyZTY5MGYwXkEyXkFqcGc%40._V1_.jpg',trailer='E_p4kHzZBTM',sourceUrl='https://en.wikipedia.org/wiki/Pratikshya',languages=['Odia'],industry='Ollywood',regionOfOrigin='Odia'))
add(dict(base,id=610000000003,title='Dahaan',year=2026,genres=['Horror'],cast=['Barsha Patnaik','Partha Sarathi Ray','Aurosikha Mishra','Samrat Mahapatra'],director='Anupam Patnaik',summary='A supernatural horror story unfolds around a family and a mysterious ancestral house.',poster='https://image.tmdb.org/t/p/w500/6ThwhGmO8wLQ8xj6d8hkUSWmd6O.jpg',trailer='MwuGY3qVooY',source='Amiya Patnaik Production',sourceUrl='https://dahaan.in/',languages=['Odia'],industry='Ollywood',regionOfOrigin='Odia'))
add(dict(base,id=610000000004,title='Jawan',year=2023,genres=['Action','Thriller'],cast=['Shah Rukh Khan','Nayanthara','Vijay Sethupathi','Deepika Padukone'],director='Atlee',runtime=169,summary='A mysterious vigilante challenges corruption while confronting a dangerous figure from his past.',poster='https://images.herzindagi.info/image/2024/Jul/jawan-cast.jpg',trailer='COv52Qyctws',sourceUrl='https://en.wikipedia.org/wiki/Jawan_(film)',languages=['Hindi'],industry='Bollywood',regionOfOrigin='Hindi',providers=[dict(name='Netflix',region='GLOBAL',url='https://www.netflix.com/title/81493411',type='official-title',checkedAt='2026-10-27')]))
(root/'dist/movies.json').write_text(json.dumps(curated,ensure_ascii=False,indent=2));(root/'dist/archive.json').write_text(json.dumps(archive,ensure_ascii=False,separators=(',',':')));(root/'src/Cineclay.Api/seed.json').write_text(json.dumps(curated,ensure_ascii=False,indent=2))
report=json.loads((root/'dist/catalog-report.json').read_text());report.update(fetchedAt='2026-10-27',movies=sum(m.get('mediaType','movie')=='movie' for m in curated)+len(archive),tvSeries=sum(m.get('mediaType')=='tv' for m in curated),indexOnly=len(archive),enriched=len(curated),scope='Wikipedia American, Hindi, and selected Odia film lists; selected TVmaze series. Not a complete worldwide catalog.');report['languages']=sorted({l for m in curated+archive for l in m.get('languages',[])});(root/'dist/catalog-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print('Catalog',report['movies'],'movies,',report['tvSeries'],'series;',sum('Odia' in m.get('languages',[]) for m in curated+archive),'Odia titles')
